const emails = $input.first().json.value || [];
if (!emails.length) return [];
return emails.map(email => ({ json: email }));

const norm = $('Normalizar campos').first().json;
const aiRaw = $json.content?.[0]?.text || '{}';

// Limpar markdown se presente
let cleaned = aiRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let ai = {};
try {
  ai = JSON.parse(cleaned);
} catch(e) {
  // Tentar extrair JSON com regex
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { ai = JSON.parse(match[0]); } catch(e2) {
      ai = { category: 'outro', urgency: 'normal', summary: 'Erro ao processar IA' };
    }
  } else {
    ai = { category: 'outro', urgency: 'normal', summary: 'IA não devolveu JSON válido' };
  }
}

const slaMap = {
  pedido_orcamento:4, reclamacao:2, followup_cliente:8,
  compra_cliente:4, compra_fornecedor:24, fornecedor_sourcing:72,
  fornecedor_novidade:9999, tabela_precos_fornecedor:72, fatura_administrativo:48, spam:9999, outro:24
};
const hrs = slaMap[ai.category] || 24;
const sla = (ai.category === 'spam' || ai.category === 'fornecedor_novidade') ? null : new Date(Date.now() + hrs * 3600000).toISOString();

return [{json: {
  mailbox: norm.mailbox,
  subject: norm.subject,
  fromAddress: norm.fromAddress,
  toAddress: norm.toAddress,
  bodyText: norm.bodyText,
  receivedAt: norm.receivedAt,
  graphMessageId: norm.graphMessageId,
  threadIdExt: norm.threadIdExt,
  msToken: norm.msToken,
  category: ai.category || 'outro',
  urgency: ai.urgency || 'normal',
  ai_summary: ai.summary || '',
  ai_draft: null,
  sla_due_at: sla,
  contact_name: ai.contact_name || null,
  contact_phone: ai.contact_phone || null,
  nif: ai.nif || null,
  address: ai.address || null,
  city: ai.city || null,
  postal_code: ai.postal_code || null,
  website: ai.website || null,
  request_type: ai.request_type || null,
  requested_items: ai.requested_items || null,
  contact_role: ai.contact_role || null
}}];

