const items = $input.all();
const out = [];

// messageId e directusToken perdem-se ao passar pelo nó HTTP "GET Attachments 
// List (Graph)" (que substitui $json pela resposta da Graph API) — por isso
// vamos buscá-los directamente ao nó de origem (Prep Attachments), não ao 
// input imediato.
let ctx;
try {
  ctx = $('Prep Attachments (novo)').first().json;
} catch (e) {
  ctx = $('Prep Attachments (existente)').first().json;
}

for (const item of items) {
  const attachments = item.json.value || item.json.attachments || [];
  for (const att of attachments) {
    if (att['@odata.type'] !== '#microsoft.graph.fileAttachment') continue;
    if (!att.contentBytes) continue;
    const buffer = Buffer.from(att.contentBytes, 'base64');
    const binaryData = await this.helpers.prepareBinaryData(
      buffer,
      att.name || 'anexo',
      att.contentType || 'application/octet-stream'
    );
    out.push({
      json: {
        messageId: ctx.messageId,
        directusToken: ctx.directusToken,
        filename: att.name || 'anexo',
        size: att.size || buffer.length,
      },
      binary: { file: binaryData },
    });
  }
}
if (out.length === 0) {
  return [{ json: { skip: true, messageId: ctx.messageId } }];
}
return out;

const uploads = $input.all();
const prep = $('Prepare Attachment Binaries').all();
const messageId = prep[0]?.json?.messageId || uploads[0]?.json?.messageId;
const attachments = [];
for (let i = 0; i < uploads.length; i++) {
  const u = uploads[i].json;
  if (u.error || !u.data?.id) continue;
  const meta = prep[i]?.json || {};
  attachments.push({ file: u.data.id, filename: meta.filename || u.data.filename_download, size: meta.size || Number(u.data.filesize) || 0 });
}
return [{ json: { messageId, attachments } }];

const directusUrl = 'https://api.hotelequip.pt';
const directusToken = process.env.DIRECTUS_N8N_TOKEN || '__REDACTED_SEE_N8N_CREDENTIALS__'; // NOTA: token real vive só no n8n; nunca commitar em claro

const ia = $('Tratar IA + calcular SLA').first().json;
const fromAddress = ($json.fromAddress || '').trim().toLowerCase();
const mailbox = $json.mailbox || '';

// Caixas próprias da Hotelequip — nunca criar lead se o remetente for uma delas
const OWN_MAILBOXES = ['geral@hotelequip.pt', 'apoio.cliente@hotelequip.pt'];

if (!fromAddress || fromAddress === mailbox.toLowerCase() || OWN_MAILBOXES.includes(fromAddress)) {
  return [{ json: { skipped: true, reason: 'sem remetente válido ou é caixa própria' } }];
}

// Gate de encaminhamento por categoria — só estas categorias criam/actualizam lead
const NO_LEAD_CATEGORIES = ['spam', 'fatura_administrativo', 'tabela_precos_fornecedor', 'fornecedor_sourcing', 'fornecedor_novidade', 'compra_fornecedor'];
const category = ia.category || 'outro';

if (NO_LEAD_CATEGORIES.includes(category)) {
  return [{ json: { skipped: true, reason: `categoria '${category}' não cria lead` } }];
}

try {
  // 1) já é contacto?
  const contactRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${directusUrl}/items/contacts`,
    qs: { 'filter[email][_eq]': fromAddress, limit: 1, fields: 'id,company_name' },
    headers: { Authorization: `Bearer ${directusToken}` },
    json: true,
  });
  if (contactRes?.data?.length) {
    return [{ json: { found: 'contact', id: contactRes.data[0].id } }];
  }

  // 2) já é lead (não descartado)?
  const leadRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${directusUrl}/items/leads`,
    qs: { 'filter[email][_eq]': fromAddress, 'filter[status][_neq]': 'discarded', limit: 1, fields: 'id' },
    headers: { Authorization: `Bearer ${directusToken}` },
    json: true,
  });
  if (leadRes?.data?.length) {
    return [{ json: { found: 'lead', id: leadRes.data[0].id } }];
  }

  // 3) desconhecido: cria lead nova, já povoada com tudo o que a IA extraiu
  const fallbackName = fromAddress.split('@')[0].replace(/[._-]/g, ' ');
  const displayName = (ia.contact_name || fallbackName || '').slice(0, 120);

  const notesParts = [];
  if (ia.request_type) notesParts.push(`Tipo: ${ia.request_type}`);
  if (ia.requested_items) notesParts.push(`Itens: ${ia.requested_items}`);
  if (ia.contact_role) notesParts.push(`Papel: ${ia.contact_role}`);
  const notes = notesParts.length > 0 ? notesParts.join(' | ') : undefined;

  const leadPayload = {
    email: fromAddress,
    display_name: displayName,
    source: 'email_inbound',
    status: 'new',
    contact_name: ia.contact_name || undefined,
    contact_phone: ia.contact_phone || undefined,
    nif: ia.nif || undefined,
    city: ia.city || undefined,
    postal_code: ia.postal_code || undefined,
    website: ia.website || undefined,
    notes,
    lead_data: {
      company_name: ia.contact_name && ia.contact_name !== displayName ? undefined : displayName,
      contact_name: ia.contact_name || undefined,
      phone: ia.contact_phone || undefined,
      address: ia.address || undefined,
      city: ia.city || undefined,
      postal_code: ia.postal_code || undefined,
      website: ia.website || undefined,
      contact_role: ia.contact_role || undefined,
      request_type: ia.request_type || undefined,
      requested_items: ia.requested_items || undefined,
      email_thread_category: category,
    },
  };

  const createRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${directusUrl}/items/leads`,
    headers: { Authorization: `Bearer ${directusToken}`, 'Content-Type': 'application/json' },
    body: leadPayload,
    json: true,
  });
  return [{ json: { found: 'none', createdLeadId: createRes?.data?.id || null } }];
} catch (err) {
  return [{ json: { error: (err?.message || String(err)).slice(0, 200) } }];
}

